<template>
  <div class="login-container">
    <div class="login-wrapper">
      <div class="login-brand">
        <el-icon :size="60"><Monitor /></el-icon>
        <h1>实验室设备管理系统</h1>
        <p>专业、严谨、高效的资产管理平台</p>
      </div>
      
      <el-card class="login-card">
        <div class="form-header">
          <span :class="{ active: mode === 'login' }" @click="mode = 'login'">账号登录</span>
          <span class="divider">|</span>
          <span :class="{ active: mode === 'register' }" @click="mode = 'register'">快速注册</span>
        </div>
        
        <!-- 登录表单 -->
        <el-form v-if="mode === 'login'" :model="loginForm" :rules="loginRules" ref="loginFormRef" label-width="0">
          <el-form-item prop="username">
            <el-input 
              v-model="loginForm.username" 
              placeholder="请输入学号 / 工号" 
              :prefix-icon="Postcard"
              size="large"
            />
          </el-form-item>
          
          <el-form-item prop="password">
            <el-input 
              v-model="loginForm.password" 
              type="password" 
              placeholder="请输入密码" 
              :prefix-icon="Lock"
              size="large"
              show-password
              @keyup.enter="handleLogin"
            />
          </el-form-item>
          
          <el-button 
            type="primary" 
            :loading="loading" 
            class="submit-button" 
            size="large"
            @click="handleLogin"
          >
            登 录
          </el-button>
        </el-form>
        
        <!-- 注册表单 -->
        <el-form v-else :model="registerForm" :rules="registerRules" ref="registerFormRef" label-width="0">
          <el-form-item prop="name">
            <el-input v-model="registerForm.name" placeholder="真实姓名" :prefix-icon="UserFilled" size="large" />
          </el-form-item>
          <el-form-item prop="student_id">
            <el-input v-model="registerForm.student_id" placeholder="学号 / 工号" :prefix-icon="Postcard" size="large" />
          </el-form-item>
          <el-form-item prop="password">
            <el-input v-model="registerForm.password" type="password" placeholder="设置密码" :prefix-icon="Lock" size="large" show-password />
          </el-form-item>
          <el-form-item prop="role">
            <el-select v-model="registerForm.role" placeholder="选择身份角色" size="large" style="width: 100%">
              <el-option
                v-for="role in meta.roles"
                :key="role.code"
                :label="role.label"
                :value="role.code"
              />
            </el-select>
          </el-form-item>
          
          <el-button 
            type="success" 
            :loading="loading" 
            class="submit-button" 
            size="large"
            @click="handleRegister"
          >
            注 册
          </el-button>
        </el-form>
        
        <div class="login-footer">
          <p v-if="mode === 'login'">学号或工号不存在请先注册</p>
          <p v-else>注册后需联系管理员审核权限</p>
        </div>
      </el-card>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { User, Lock, Monitor, UserFilled, Postcard } from '@element-plus/icons-vue'
import api from '@/api'

const router = useRouter()
const mode = ref('login')
const loading = ref(false)
const loginFormRef = ref(null)
const registerFormRef = ref(null)
const meta = ref({ roles: [] })

const loginForm = reactive({
  username: '',
  password: ''
})

const registerForm = reactive({
  username: '',
  password: '',
  name: '',
  student_id: '',
  role: '硕士生'
})

const loginRules = {
  username: [{ required: true, message: '请输入学号/工号', trigger: 'blur' }],
  password: [{ required: true, message: '请输入密码', trigger: 'blur' }]
}

const registerRules = {
  password: [{ required: true, message: '请设置密码', trigger: 'blur' }, { min: 6, message: '密码长度不能小于6位', trigger: 'blur' }],
  name: [{ required: true, message: '请输入真实姓名', trigger: 'blur' }],
  student_id: [{ required: true, message: '请输入学号/工号', trigger: 'blur' }]
}

const handleLogin = async () => {
  if (!loginFormRef.value) return
  await loginFormRef.value.validate(async (valid) => {
    if (valid) {
      loading.value = true
      try {
        const response = await api.login(loginForm.username, loginForm.password)
        // 保存token和用户信息
        localStorage.setItem('access_token', response.data.access_token)
        localStorage.setItem('refresh_token', response.data.refresh_token)
        localStorage.setItem('user', JSON.stringify(response.data.user))
        ElMessage.success('登录成功')
        router.push('/')
      } catch (error) {
        ElMessage.error(error.response?.data?.error || '登录失败，请检查账号密码')
      } finally {
        loading.value = false
      }
    }
  })
}

const handleRegister = async () => {
  if (!registerFormRef.value) return
  await registerFormRef.value.validate(async (valid) => {
    if (valid) {
      loading.value = true
      try {
        await api.register({
          ...registerForm,
          username: registerForm.student_id
        })
        ElMessage.success('注册成功，请登录')
        mode.value = 'login'
      } catch (error) {
        ElMessage.error(error.response?.data?.error || '注册失败')
      } finally {
        loading.value = false
      }
    }
  })
}

onMounted(() => {
  api.getMeta().then(r => { meta.value = r.data || {} }).catch(() => {})
})
</script>

